pub const Category = enum(u8) {
    Lu,
    Ll,
    Lt,
    Lm,
    Lo,
    Mn,
    Mc,
    Me,
    Nd,
    Nl,
    No,
    Pc,
    Pd,
    Ps,
    Pe,
    Pi,
    Pf,
    Po,
    Sm,
    Sc,
    Sk,
    So,
    Zs,
    Zl,
    Zp,
    Cc,
    Cf,
    Cs,
    Co,
    Cn,
};

pub fn rangesFor(cat: Category) []const Range {
    return switch (cat) {
        .Lu => &gc_Lu,
        .Ll => &gc_Ll,
        .Lt => &gc_Lt,
        .Lm => &gc_Lm,
        .Lo => &gc_Lo,
        .Mn => &gc_Mn,
        .Mc => &gc_Mc,
        .Me => &gc_Me,
        .Nd => &gc_Nd,
        .Nl => &gc_Nl,
        .No => &gc_No,
        .Pc => &gc_Pc,
        .Pd => &gc_Pd,
        .Ps => &gc_Ps,
        .Pe => &gc_Pe,
        .Pi => &gc_Pi,
        .Pf => &gc_Pf,
        .Po => &gc_Po,
        .Sm => &gc_Sm,
        .Sc => &gc_Sc,
        .Sk => &gc_Sk,
        .So => &gc_So,
        .Zs => &gc_Zs,
        .Zl => &gc_Zl,
        .Zp => &gc_Zp,
        .Cc => &gc_Cc,
        .Cf => &gc_Cf,
        .Cs => &gc_Cs,
        .Co => &gc_Co,
        .Cn => &gc_Cn,
    };
}

